import{_ as t,I as a,g as o,j as i}from"./chunks/framework.CjoWWfVe.js";const p=JSON.parse('{"title":"Raw Materials (Materials Stock)","description":"How batch inventory accounting, logistics, and MAC (Moving Average Cost) work in OmniCraft ERP.","frontmatter":{"title":"Raw Materials (Materials Stock)","description":"How batch inventory accounting, logistics, and MAC (Moving Average Cost) work in OmniCraft ERP.","order":5},"headers":[],"relativePath":"docs/spaces/production/warehouse.md","filePath":"docs/spaces/production/warehouse.md"}'),r={name:"docs/spaces/production/warehouse.md"};function n(s,e,l,c,h,d){return a(),o("div",null,[...e[0]||(e[0]=[i('<h1 id="📦-raw-materials-materials-stock-batch-purchases" tabindex="-1">📦 Raw Materials: Materials Stock &amp; Batch Purchases <a class="header-anchor" href="#📦-raw-materials-materials-stock-batch-purchases" aria-label="Permalink to &quot;📦 Raw Materials: Materials Stock &amp; Batch Purchases&quot;">​</a></h1><p>The <strong>&quot;Materials&quot;</strong> tab is the logistical heart of your craft business. Here, you store all materials physically used in production: leather, thread, glue, hardware, fabric, wood, and packaging.</p><p>OmniCraft ERP utilizes a professional cost-accounting method: <strong>MAC (Moving Average Cost)</strong>, saving you from manually calculating how much a square foot of leather costs after factoring in shipping.</p><hr><h2 id="📋-material-profile" tabindex="-1">📋 Material Profile <a class="header-anchor" href="#📋-material-profile" aria-label="Permalink to &quot;📋 Material Profile&quot;">​</a></h2><p>Before purchasing a material, you need to add it to your inventory database. Click the <strong>&quot;+&quot; (New Material)</strong> button on the top toolbar.</p><p>In the material profile, you specify:</p><ul><li><strong>Name:</strong> For example, <em>“Cambrian Clay (Dry Powder)”</em> or <em>“Oat Straw (2-4 cm)”</em>.</li><li><strong>Category:</strong> Grouping for organization (e.g., <em>“Clay”</em>, <em>“Straw &amp; Fibers”</em>, <em>“Binders”</em>). Categories can be edited on the fly by clicking the pencil icon.</li><li><strong>Units of Measurement:</strong> What unit you will use to measure the material in your recipes (kg, pcs, ml, liters). <em>Important: Choose the unit that is most convenient for calculating consumption per single item.</em></li><li><strong>Min. Stock (Safety Threshold):</strong> The value at which the balance in the table will be highlighted in yellow (deficit warning). <em>💡 Smart Auto-Calculation:</em> If you leave this field as <code>0</code>, the program will <strong>dynamically calculate the threshold itself</strong> (by default, 20% of the average volume of your last 20 purchases of this raw material). Discrete items are smartly rounded to whole numbers. You can change the percentage or completely disable auto-calculation in the Tab Settings (⚙️ icon in the top menu).</li></ul><h3 id="🔗-managing-suppliers-and-links" tabindex="-1">🔗 Managing Suppliers and Links <a class="header-anchor" href="#🔗-managing-suppliers-and-links" aria-label="Permalink to &quot;🔗 Managing Suppliers and Links&quot;">​</a></h3><p>If you click the <strong>&quot;Edit&quot;</strong> (✏️) icon next to a material, its detailed profile will open. There, you can attach multiple links to the same or different suppliers (for example, adding both retail and wholesale purchase links for a specific type of clay or straw).</p><p>To keep the main stock table clean and organized, link management uses an adaptive interface:</p><ul><li>⭐ <strong>&quot;Show in Table&quot;:</strong> Default status. All active suppliers will be neatly collapsed into a <code>(+N)</code> badge in the main table. Clicking the badge opens a list for quick navigation. If you unstar a link, it moves to the reserve list (turns gray) and is hidden from the main table, while remaining available during batch purchases.</li><li>📌 <strong>&quot;Pin&quot;:</strong> Elevates a selected link to the top of the active list.</li><li>✅ <strong>&quot;Set as Primary&quot;:</strong> This radio button appears if you have pinned multiple links. It allows you to select the <em>single</em> primary link displayed directly in the main stock table cell. Clicking its name in the table immediately opens the supplier&#39;s website.</li></ul><hr><h2 id="🛒-batch-purchases-logistics" tabindex="-1">🛒 Batch Purchases &amp; Logistics <a class="header-anchor" href="#🛒-batch-purchases-logistics" aria-label="Permalink to &quot;🛒 Batch Purchases &amp; Logistics&quot;">​</a></h2><p>The primary &quot;magic&quot; of OmniCraft ERP lies within the <strong>&quot;Batch Purchase&quot;</strong> button (the shopping cart icon in the top menu). Never enter purchased materials via inventory adjustments—always use batch purchases!</p><h3 id="how-smart-shipping-allocation-works" tabindex="-1">How smart shipping allocation works: <a class="header-anchor" href="#how-smart-shipping-allocation-works" aria-label="Permalink to &quot;How smart shipping allocation works:&quot;">​</a></h3><p>Suppose you ordered from a supplier:</p><ol><li>A bag of Cambrian clay for <code>$100</code></li><li>A bale of oat straw for <code>$20</code></li><li>And paid a shipping fee of <code>$12</code>.</li></ol><p>If you simply split the <code>$12</code> shipping fee in half (<code>$6</code> per item), the cost price of the cheap straw would skyrocket, heavily distorting the cost price of your finished products.</p><p><strong>OmniCraft ERP allocates shipping proportionally to the value of the items:</strong></p><ul><li>The clay (<code>$100</code>) absorbs <code>$10</code> of the shipping cost.</li><li>The straw (<code>$20</code>) absorbs only <code>$2</code> of the shipping cost. The software performs this calculation in a fraction of a second, logging a fair and balanced cost price for each item in your warehouse.</li></ul><h3 id="what-happens-when-you-process-a-purchase" tabindex="-1">What happens when you process a purchase: <a class="header-anchor" href="#what-happens-when-you-process-a-purchase" aria-label="Permalink to &quot;What happens when you process a purchase:&quot;">​</a></h3><ol><li>The physical quantity of materials is added to your stock.</li><li>The program recalculates the <strong>MAC price</strong>. If you had remaining clay at an older price and purchased a new batch at a higher price, the software automatically averages their cost.</li><li>In your <strong>Cash Flow</strong> ledger, two expense entries are automatically created: <em>“Purchase of Raw Materials”</em> (for <code>$120</code>) and <em>“Logistics”</em> (for <code>$12</code>).</li></ol><hr><h2 id="🖨️-warehouse-labeling-and-printing" tabindex="-1">🖨️ Warehouse Labeling and Printing <a class="header-anchor" href="#🖨️-warehouse-labeling-and-printing" aria-label="Permalink to &quot;🖨️ Warehouse Labeling and Printing&quot;">​</a></h2><p>The program features a built-in, 100% offline label generator supporting both thermal printers (rolls) and standard office printers (A4 sticker sheets). You can print labels individually from the material card (the <strong>&quot;Print label&quot;</strong> button) or in batches for the entire rack by clicking <strong>&quot;Batch print labels&quot;</strong> in the top warehouse panel.</p><h3 id="coding-modes-what-s-on-the-label" tabindex="-1">Coding Modes (What&#39;s on the label) <a class="header-anchor" href="#coding-modes-what-s-on-the-label" aria-label="Permalink to &quot;Coding Modes (What&#39;s on the label)&quot;">​</a></h3><p>Depending on the label size, you can place one or several useful codes:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Mode</th><th style="text-align:left;">How it works</th><th style="text-align:left;">Practical Example</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>SKU</strong></td><td style="text-align:left;">Linear barcode (Code128).</td><td style="text-align:left;">You point the scanner at a jar of straw ➔ the program instantly finds it in the warehouse.</td></tr><tr><td style="text-align:left;"><strong>Order from supplier</strong></td><td style="text-align:left;">QR code with a direct link to the store.</td><td style="text-align:left;">Point your phone camera at the separating oil shelf ➔ the reorder website opens. If there are multiple suppliers, a handy list opens.</td></tr><tr><td style="text-align:left;"><strong>Material passport</strong></td><td style="text-align:left;">QR code with text characteristics.</td><td style="text-align:left;">Point your phone at a box of clay on the top shelf ➔ the balance and location are shown in large text without internet.</td></tr><tr><td style="text-align:left;"><strong>SKU + Order</strong></td><td style="text-align:left;">Combo mode (barcode at the bottom, QR on the side).</td><td style="text-align:left;">Ideal for medium stickers (from 58×40 mm).</td></tr><tr><td style="text-align:left;"><strong>SKU + Order + Passport</strong></td><td style="text-align:left;">Trio-Maxi: barcode and two QR codes.</td><td style="text-align:left;">For large boxes and pallets (from 100×75 mm).</td></tr><tr><td style="text-align:left;"><strong>Text only</strong></td><td style="text-align:left;">Large readable font without codes.</td><td style="text-align:left;">For the smallest jars (30×20 mm).</td></tr></tbody></table><h3 id="🎛️-print-settings-borders-calibration" tabindex="-1">🎛️ Print Settings (Borders &amp; Calibration) <a class="header-anchor" href="#🎛️-print-settings-borders-calibration" aria-label="Permalink to &quot;🎛️ Print Settings (Borders &amp; Calibration)&quot;">​</a></h3><p>When printing, you can select the <strong>Border / Outline</strong> type:</p><ul><li><strong>No border:</strong> Ideal for pre-cut factory self-adhesive label sheets (e.g., Lomond/Avery). Leaving borders off ensures that minor printer paper skew will not cause black border lines to bleed onto adjacent stickers.</li><li><strong>Dashed (Cutting guide):</strong> Used when printing on regular A4 sheets for easy trimming with scissors or a rotary cutter.</li><li><strong>Solid border:</strong> A clean decorative outline, perfect for printing hang tags on heavy kraft cardstock for your crafted goods.</li></ul><div class="tip custom-block"><p class="custom-block-title">🛠️ Printer Calibration (Offset Compensation)</p><p>When printing on A4 sheets, feed rollers can shift printouts down by 3–5 mm, while thermal roll printers may experience 1–2 mm drift due to gap sensor calibration or tape play.</p><p>To achieve 100% accurate alignment on any printer model, use the <strong>Printer Calibration (mm)</strong> controls:</p><ul><li><strong>Shift Y (mm):</strong> Adjusts vertical alignment (e.g., <code>-3.0</code> shifts content up by 3 mm).</li><li><strong>Shift X (mm):</strong> Adjusts horizontal alignment (left/right).</li></ul><p>Set your hardware offset once—the software automatically saves it for all future print jobs.</p></div><div class="tip custom-block"><p class="custom-block-title">📱 Smartphone instead of a scanner</p><p>You don&#39;t have to buy an expensive USB scanner. You can install a free app on your phone (e.g., Barcode to PC or any Bluetooth keyboard emulator). Your phone will read barcodes and instantly &quot;type&quot; SKUs into the OmniCraft ERP search bar on your computer.</p></div><hr><h2 id="⚖️-inventory-adjustment-stock-correction" tabindex="-1">⚖️ Inventory Adjustment (Stock Correction) <a class="header-anchor" href="#⚖️-inventory-adjustment-stock-correction" aria-label="Permalink to &quot;⚖️ Inventory Adjustment (Stock Correction)&quot;">​</a></h2><p>The <strong>&quot;Inventory Adjustment&quot;</strong> button (the scale icon) is used <strong>only</strong> to correct physical discrepancies in your warehouse.</p><p>For example, if the software shows you have 15 kg of clay left, but physically it has dried out and cannot be crafted into anything, you perform an inventory adjustment and write off the deficit.</p><ul><li><strong>Financial Safety:</strong> Inventory adjustments <strong>do not</strong> touch your Cash Flow ledger or Balance Sheet. They only adjust physical quantities, preventing the program from letting you schedule production with non-existent materials.</li></ul><hr><h2 id="🗄️-archiving-deletion" tabindex="-1">🗄️ Archiving &amp; Deletion <a class="header-anchor" href="#🗄️-archiving-deletion" aria-label="Permalink to &quot;🗄️ Archiving &amp; Deletion&quot;">​</a></h2><p>If you stop working with a specific material (for example, a supplier discontinues a certain edge paint), you can send it to the <strong>Archive</strong> (the red box icon).</p><ul><li>The material will disappear from your active list, keeping search results clean.</li><li>When moving an item to the archive, the program will suggest <strong>zeroing out remaining stock</strong> if there is any left.</li><li>An archived material can be restored at any time by switching to the &quot;Archived&quot; tab.</li></ul><div class="warning custom-block"><p class="custom-block-title">Archiving Blocked</p><p>You cannot send a material to the archive if it is currently used in at least one active product template (in the Calculator) or if there is an uncompleted workbench job that requires it. The software will display a window listing the exact items blocking the archive operation. You will need to update those recipes first.</p></div><hr><h2 id="⚙️-raw-materials-tab-settings" tabindex="-1">⚙️ Raw Materials Tab Settings <a class="header-anchor" href="#⚙️-raw-materials-tab-settings" aria-label="Permalink to &quot;⚙️ Raw Materials Tab Settings&quot;">​</a></h2><p>To customize the interface to your workflow, click the <strong>Raw Materials Settings</strong> (sliders) icon in the top toolbar.</p><ul><li><strong>Column Visibility:</strong> Hide unused columns (such as SKU or Location) to free up screen real estate.</li><li><strong>Table Action Buttons Visibility:</strong> Flexibly toggle the quick action icons in each table row (<em>Purchase Raw Materials, Inventory Adjustment, Print Label, Edit, Archive / Delete</em>). Leave only the actions you use daily to prevent accidental clicks.</li><li><strong>Automatic Minimum Stock Calculation:</strong> Configure the percentage for dynamic deficit thresholds (detailed in the &quot;Material Profile&quot; section).</li></ul><hr><h2 id="↩️-cancelling-operations-storno" tabindex="-1">↩️ Cancelling Operations (Storno) <a class="header-anchor" href="#↩️-cancelling-operations-storno" aria-label="Permalink to &quot;↩️ Cancelling Operations (Storno)&quot;">​</a></h2><p>If you made a mistake during a purchase or inventory adjustment, you can cancel the operation directly from the <strong>Operations Log</strong> or the material passport.</p><ol><li>Click the <strong>Undo (↩️)</strong> icon next to the erroneous operation.</li><li>The program will automatically create a corrective entry (<strong>Storno</strong>), returning the physical stock to its previous state.</li><li>If a purchase with a specified price or shipping cost is cancelled, the spent funds are automatically returned to the Cash Flow (DDS).</li></ol><div class="warning custom-block"><p class="custom-block-title">Cancellation Limits</p><ul><li><strong>MAC Method Protection (Historical Purchases):</strong> You cannot cancel a purchase if other operations changing the balance of this raw material have been performed after it. This is necessary to protect the weighted average price. To cancel an old purchase, you must first cancel all newer operations with this material.</li><li><strong>Workbench Write-offs:</strong> Write-offs made during the production of finished goods cannot be cancelled through the raw materials warehouse. To cancel them, go to the &#39;Production&#39; tab and cancel the corresponding order.</li></ul></div>',53)])])}const g=t(r,[["render",n]]);export{p as __pageData,g as default};
